import{_ as e,o as a,c as l,a2 as i}from"./chunks/framework.CBxkvBm_.js";const g=JSON.parse('{"title":"CLI Overview","description":"","frontmatter":{},"headers":[],"relativePath":"cli/overview.md","filePath":"cli/overview.md"}'),d={name:"cli/overview.md"};function s(n,t,o,r,c,m){return a(),l("div",null,[...t[0]||(t[0]=[i(`<h1 id="cli-overview" tabindex="-1">CLI Overview <a class="header-anchor" href="#cli-overview" aria-label="Permalink to &quot;CLI Overview&quot;">​</a></h1><p>The <code>@modelscript/cli</code> package provides two identical binary executables: <code>modelscript</code> and its shorthand alias <code>msx</code>. The command-line interface serves as the primary headless automation driver for compiling, simulating, verifying, linting, rendering, and orchestrating polyglot engineering systems across local workspaces, CI/CD pipelines, and cloud HPC clusters.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>You can run the CLI directly from the monorepo workspace using <code>npx</code>, or install it globally for system-wide access:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run directly via npx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> msx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install globally</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @modelscript/cli</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><h2 id="global-options-environment-variables" tabindex="-1">Global Options &amp; Environment Variables <a class="header-anchor" href="#global-options-environment-variables" aria-label="Permalink to &quot;Global Options &amp; Environment Variables&quot;">​</a></h2><p>The CLI parser (<code>apps/cli/src/main.ts</code>) intercepts global execution flags prior to command dispatch and respects standard environment variables for headless CI/CD and enterprise hub integration:</p><h3 id="global-flags" tabindex="-1">Global Flags <a class="header-anchor" href="#global-flags" aria-label="Permalink to &quot;Global Flags&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Flag</th><th style="text-align:left;">Type</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>--daemon</code></td><td style="text-align:left;"><code>boolean</code></td><td style="text-align:left;">Route command execution through the persistent background compiler daemon (<code>~/.modelscript/daemon.sock</code>) to bypass cold-start WASM initialization and reuse warm Salsa caches.</td></tr><tr><td style="text-align:left;"><code>--help</code></td><td style="text-align:left;"><code>boolean</code></td><td style="text-align:left;">Display usage information and command-specific options.</td></tr><tr><td style="text-align:left;"><code>--version</code></td><td style="text-align:left;"><code>boolean</code></td><td style="text-align:left;">Print the installed <code>@modelscript/cli</code> semantic version.</td></tr></tbody></table><h3 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Variable</th><th style="text-align:left;">Default</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>NO_COLOR</code></td><td style="text-align:left;">Unset</td><td style="text-align:left;">When set to any non-empty value, disables ANSI color sequences in terminal diagnostics, tables, and diff output.</td></tr><tr><td style="text-align:left;"><code>MODELSCRIPT_API_URL</code></td><td style="text-align:left;"><code>http://localhost:3000</code></td><td style="text-align:left;">Base URL for the ModelScript Hub, Package Registry, and Cloud HPC dispatch API (<code>~/.modelscriptrc</code> fallback).</td></tr><tr><td style="text-align:left;"><code>MODELSCRIPT_TOKEN</code></td><td style="text-align:left;">Unset</td><td style="text-align:left;">Bearer token (<code>JWT</code> or <code>ms_bot_*</code> service token) used for non-interactive authentication against the Registry, Cloud HPC, and Hub APIs (also accepts <code>MODELSCRIPT_API_TOKEN</code>).</td></tr></tbody></table><h2 id="persistent-compiler-daemon-daemon" tabindex="-1">Persistent Compiler Daemon (<code>--daemon</code>) <a class="header-anchor" href="#persistent-compiler-daemon-daemon" aria-label="Permalink to &quot;Persistent Compiler Daemon (\`--daemon\`)&quot;">​</a></h2><p>Standard CLI invocations spin up an isolated Node.js process, compile or load <code>.wasm</code> parser binaries, and index workspace dependencies from disk. When iterating rapidly or running hundreds of checks in a pre-commit hook, pass <code>--daemon</code> to any command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start or auto-spawn the background daemon and run lint with warm Salsa caches</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model.mo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --daemon</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Explicitly manage the daemon lifecycle</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daemon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daemon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daemon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span></span></code></pre></div><p>When <code>--daemon</code> is passed, <code>msx</code> connects to the local Unix domain socket (<code>~/.modelscript/daemon.sock</code> on Linux/macOS or named pipe <code>\\\\.\\pipe\\modelscript-daemon</code> on Windows). If no daemon is running, the CLI automatically spawns one in the background, waits for readiness, and streams the command&#39;s <code>stdout</code>, <code>stderr</code>, and exit code back to the terminal.</p><h2 id="complete-command-reference-by-category" tabindex="-1">Complete Command Reference by Category <a class="header-anchor" href="#complete-command-reference-by-category" aria-label="Permalink to &quot;Complete Command Reference by Category&quot;">​</a></h2><p>The <code>msx</code> CLI registers <strong>41 commands</strong> (plus ergonomic aliases) organized into six functional domains. See <a href="./commands.html">CLI Commands</a> for exhaustive flag tables and examples for every command.</p><h3 id="_1-compilation-simulation-optimization" tabindex="-1">1. Compilation, Simulation &amp; Optimization <a class="header-anchor" href="#_1-compilation-simulation-optimization" aria-label="Permalink to &quot;1. Compilation, Simulation &amp; Optimization&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">Aliases</th><th style="text-align:left;">Summary</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./commands.html#compile-flatten"><code>compile</code></a></td><td style="text-align:left;"><code>flatten</code></td><td style="text-align:left;">Flatten a Modelica class hierarchy into a canonical Differential-Algebraic Equation (DAE) system.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#instantiate"><code>instantiate</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Instantiate a Modelica class and print its resolved component and equation structure.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#simulate"><code>simulate</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Execute numerical DAE/ODE time-domain or steady-state simulations (JS, Arena, WASM, C, JIT, WebGPU, or Cloud HPC).</td></tr><tr><td style="text-align:left;"><a href="./commands.html#optimize"><code>optimize</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Solve nonlinear Dynamic Optimization and Optimal Control Problems (OCP) via direct collocation.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#grad"><code>grad</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Compute forward/adjoint parameter sensitivities ($\\partial J / \\partial p$) and finite-difference gradients.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#surrogate"><code>surrogate</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Run Design of Experiments (DoE), train Neural/Polynomial/RBF surrogates, and export ONNX/C/Modelica ROMs.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#mc"><code>mc</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Execute multi-threaded Monte Carlo uncertainty quantification and reliability sweeps.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#csg"><code>csg</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Extract Constructive Solid Geometry (CSG) primitives from Modelica models into 3D CAD meshes.</td></tr></tbody></table><h3 id="_2-linting-formatting-diffing-localization" tabindex="-1">2. Linting, Formatting, Diffing &amp; Localization <a class="header-anchor" href="#_2-linting-formatting-diffing-localization" aria-label="Permalink to &quot;2. Linting, Formatting, Diffing &amp; Localization&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">Aliases</th><th style="text-align:left;">Summary</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./commands.html#lint"><code>lint</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Run static syntax, type, structural, and control-flow diagnostics across polyglot workspace files.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#parse"><code>parse</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Parse source files with the native WebAssembly GLR parser and inspect the concrete syntax tree (CST).</td></tr><tr><td style="text-align:left;"><a href="./commands.html#format"><code>format</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Format source files canonically using CST-preserving pretty-printing.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#unparse"><code>unparse</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Round-trip a parsed CST back into source text to verify lossless grammar unparsing.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#diff"><code>diff</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Compute structural AST/CST and semantic DAE diffs between two files or Git revisions.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#pr-diff"><code>pr-diff</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Generate visual SVG/HTML architectural diffs and Markdown PR review comments against a base Git ref.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#i18n"><code>i18n</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Extract translatable strings, compile locale catalogs, and translate model identifiers across languages.</td></tr></tbody></table><h3 id="_3-formal-verification-safety-test-synthesis" tabindex="-1">3. Formal Verification, Safety &amp; Test Synthesis <a class="header-anchor" href="#_3-formal-verification-safety-test-synthesis" aria-label="Permalink to &quot;3. Formal Verification, Safety &amp; Test Synthesis&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">Aliases</th><th style="text-align:left;">Summary</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./commands.html#verify"><code>verify</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Verify contracts, requirements, and physical invariants using BMC, $k$-induction, IC3/PDR, and Z3 SMT solving.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#falsify"><code>falsify</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Search for Signal Temporal Logic (STL) counterexamples by minimizing robustness $\\rho(\\phi, \\mathbf{x}, t)$.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#export-formal"><code>export-formal</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Export flattened DAE systems to formal verification formats (<code>smt2</code>, <code>lustre</code>, <code>nusmv</code>, <code>tla</code>, <code>keymaera</code>).</td></tr><tr><td style="text-align:left;"><a href="./commands.html#verify-decisions"><code>verify-decisions</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Verify architectural decision records (ADRs) and parameter trade-space bounds against formal system models.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#decompose"><code>decompose</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Perform assume-guarantee contract decomposition and structural subsystem partitioning.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#generate-tests"><code>generate-tests</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Synthesize MC/DC-complete unit test vectors and stimulus harnesses from formal model constraints.</td></tr></tbody></table><h3 id="_4-polyglot-digital-thread-co-simulation-standards-interop" tabindex="-1">4. Polyglot Digital Thread, Co-Simulation &amp; Standards Interop <a class="header-anchor" href="#_4-polyglot-digital-thread-co-simulation-standards-interop" aria-label="Permalink to &quot;4. Polyglot Digital Thread, Co-Simulation &amp; Standards Interop&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">Aliases</th><th style="text-align:left;">Summary</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./commands.html#render"><code>render</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Render headless SVG diagrams for Modelica icons/schematics, SysML v2 (BDD/IBD/State/Activity), and PSCAD SLDs.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#fmu"><code>fmu</code></a></td><td style="text-align:left;"><code>export-fmu</code></td><td style="text-align:left;">Package models into FMI 2.0/3.0 Functional Mock-up Units (<code>.fmu</code>) or inspect/import existing FMUs.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#import-fmu"><code>import-fmu</code></a></td><td style="text-align:left;"><code>fmu-import</code></td><td style="text-align:left;">Unpack an external <code>.fmu</code> archive and generate typed Modelica wrapper blocks and SSP bindings.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#cosim"><code>cosim</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Orchestrate and inspect distributed FMI/SSP Co-Simulation sessions, participants, and adaptive step optimizers.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#pscad"><code>pscad</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Lint, render SLDs, diff, simulate EMT transients, verify IEEE 2800 ride-through, and export <code>.pscx</code>/<code>.pswx</code> projects.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#polyglot"><code>polyglot</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Query cross-language symbol indices, verify digital thread links, and check operational digital twin drift.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#align"><code>align</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Reconcile Triple Graph Grammar (TGG) correspondences across SysML v2, Modelica, Spice, and STEP artifacts.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#sysml"><code>sysml</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Export, import, check, inspect, and bi-directionally synchronize SysML v2 <code>.sysml</code> and Modelica <code>.mo</code> models.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#oslc"><code>oslc</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Export OSLC 3.0 RDF/Turtle/JSON-LD catalogs or launch a live OSLC Tracked Resource Set (TRS 3.0) server.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#reqif"><code>reqif</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Import and export OMG ReqIF 1.2 (<code>.reqif</code> / <code>.reqifz</code>) requirements exchange archives.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#ddp"><code>ddp</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Inspect, pack, and convert ISO/PAS 81346 Digital Data Packages (<code>.ddp</code>) and Asset Administration Shells (<code>.aasx</code>).</td></tr><tr><td style="text-align:left;"><a href="./commands.html#dhf"><code>dhf</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Generate, audit, and inspect FDA 21 CFR Part 820 / ISO 13485 Design History File (DHF) compliance dossiers.</td></tr></tbody></table><h3 id="_5-language-workbench-daemon-ide-tooling" tabindex="-1">5. Language Workbench, Daemon &amp; IDE Tooling <a class="header-anchor" href="#_5-language-workbench-daemon-ide-tooling" aria-label="Permalink to &quot;5. Language Workbench, Daemon &amp; IDE Tooling&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">Aliases</th><th style="text-align:left;">Summary</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./commands.html#daemon"><code>daemon</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Manage the persistent background compiler daemon (<code>start</code>, <code>stop</code>, <code>status</code>, <code>restart</code>).</td></tr><tr><td style="text-align:left;"><a href="./commands.html#build"><code>build</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Compile a grammar DSL definition into a native WebAssembly GLR parser (<code>parser.wasm</code>) and TypeScript types.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#generate"><code>generate</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Scaffold new WASM GLR parsers or standalone VS Code language extensions from a grammar module.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#language"><code>language</code></a></td><td style="text-align:left;"><code>lang</code></td><td style="text-align:left;">List, dynamically register, or unregister custom language plugins in the workspace registry.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#lsp"><code>lsp</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Launch the multi-language ModelScript Language Server Protocol (LSP) server over <code>stdio</code> or TCP/IPC sockets.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#playground"><code>playground</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Start a local interactive web playground server for testing grammars, CSTs, and DAE compilation.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#sandbox"><code>sandbox</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Execute untrusted scripts or models inside a resource-capped, capability-isolated WebAssembly sandbox.</td></tr></tbody></table><h3 id="_6-package-registry-cloud-hpc-hub-administration" tabindex="-1">6. Package Registry, Cloud HPC &amp; Hub Administration <a class="header-anchor" href="#_6-package-registry-cloud-hpc-hub-administration" aria-label="Permalink to &quot;6. Package Registry, Cloud HPC &amp; Hub Administration&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">Aliases</th><th style="text-align:left;">Summary</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./commands.html#init"><code>init</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Initialize a new <code>modelscript.json</code> package manifest in the current directory.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#login-logout-whoami"><code>login</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Authenticate with a ModelScript Registry / Hub server and store credentials in <code>~/.modelscriptrc</code>.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#login-logout-whoami"><code>logout</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Remove stored authentication tokens from <code>~/.modelscriptrc</code>.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#login-logout-whoami"><code>whoami</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Display the currently authenticated user, organization roles, and active registry endpoint.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#install"><code>install</code></a></td><td style="text-align:left;"><code>i</code>, <code>add</code></td><td style="text-align:left;">Resolve, verify, and install versioned dependencies from the ModelScript Registry into <code>modelica_modules/</code>.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#pack-publish-unpublish"><code>pack</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Create a deterministic, SHA-256 content-addressed <code>.tgz</code> package tarball from the workspace.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#pack-publish-unpublish"><code>publish</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Sign (Ed25519) and publish a package tarball to the ModelScript Registry.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#pack-publish-unpublish"><code>unpublish</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Retract or deprecate a published package version from the registry.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#cloud"><code>cloud</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Dispatch containerized simulation and CAE jobs to remote Slurm HPC clusters and manage compute credits.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#hub-db-archive"><code>hub</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Initialize or check the health status of a self-hosted ModelScript Hub instance.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#hub-db-archive"><code>db</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Inspect, migrate, and cryptographically verify the Hub PostgreSQL database schema and audit chains.</td></tr><tr><td style="text-align:left;"><a href="./commands.html#hub-db-archive"><code>archive</code></a></td><td style="text-align:left;">—</td><td style="text-align:left;">Request, monitor, and download cold-storage compliance archives from the Hub.</td></tr></tbody></table><h2 id="return-codes-ci-cd-integration" tabindex="-1">Return Codes &amp; CI/CD Integration <a class="header-anchor" href="#return-codes-ci-cd-integration" aria-label="Permalink to &quot;Return Codes &amp; CI/CD Integration&quot;">​</a></h2><p>All <code>msx</code> commands return POSIX-compliant exit codes suitable for gating GitHub Actions, GitLab CI, or Jenkins pipelines:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Exit Code</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>0</code></td><td style="text-align:left;">Command succeeded with zero errors (or all verification obligations proved <code>SAFE</code>).</td></tr><tr><td style="text-align:left;"><code>1</code></td><td style="text-align:left;">Compilation error, static lint error (<code>severity: &quot;error&quot;</code>), counterexample falsification found, or runtime failure.</td></tr><tr><td style="text-align:left;"><code>2</code></td><td style="text-align:left;">Invalid CLI arguments, missing required flags, or unreadable input paths.</td></tr></tbody></table>`,32)])])}const f=e(d,[["render",s]]);export{g as __pageData,f as default};
